const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function initMemberNotifications({modal,toast}){
 document.addEventListener('click',async event=>{if(!event.target.closest('[data-notifications]'))return;try{const response=await fetch('/api/notifications',{credentials:'same-origin',cache:'no-store'}),result=await response.json();if(!response.ok)throw Error(result.error||'Không tải được thông báo.');const items=result.notifications;modal(`<div class="eyebrow">DEBTFREELATELY</div><h2>Thông báo của bạn</h2><div class="member-notification-list">${items.length?items.map(item=>`<article class="member-notification ${item.read?'':'unread'}"><small>${e(new Date(item.createdAt).toLocaleString('vi-VN'))}${item.read?'':' · Mới'}</small><p>${e(item.message)}</p></article>`).join(''):'<p>Bạn chưa có thông báo từ admin.</p>'}</div>`);const unread=items.filter(item=>!item.read).map(item=>item.id);if(unread.length){const marked=await fetch('/api/notifications/read',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids:unread})});if(!marked.ok)toast('Đã mở thông báo nhưng chưa cập nhật trạng thái đã đọc.');}}catch(error){toast(error.message);}});
}
